pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address oracleAddress, uint256 oracleVersion) public {
        vm.assume(oracleAddress != address(0));
        vm.assume(oracleAddress.code.length > 0);

        // Initialize C as a product. We need to become the controller (msg.sender) for initializer.
        // We mock the controller by deploying a minimal contract that can be recognized as a controller.
        // However, the initializer checks Address.isContract(msg.sender). We can use a precompile or a deployed contract.
        // Since we can't deploy extra contracts in the test, we can use the test contract itself as msg.sender
        // but Address.isContract(address(this)) will be true, so we can call initialize.
        // Note: The initializer also calls __UControllerProvider__initialize which stores msg.sender as controller.
        // So we can use the test contract as the controller.

        // Setup: Deploy a mock oracle contract at oracleAddress with code. We can use vm.etch.
        // But vm.etch is forbidden. Instead, we use a precompile address that has code, e.g., address(0x...).
        // We can also use a pre-deployed contract. Since we can't deploy extra contracts, we'll use a cheatcode to give code to an address.
        // But vm.etch is not allowed. So we use a pre-existing contract address with code (e.g., the test contract itself).
        // We can use address(this) as the oracle, but it must implement IOracleProvider. We can't deploy interfaces.
        // However, the mutant's oracle() returns address(0) regardless of what is stored internally, so we don't need the oracle to work.
        // We just need the initialization to succeed and store a non-zero address in the oracle slot.
        // The initialization calls _updateOracle which checks isContract(newOracle). So we need oracleAddress to be a contract.
        // We can use a precompile like address(0x01) which has code (sha256 precompile).
        // Assume oracleAddress is a contract by the assume above.

        // Since we cannot call initialize directly because it's initializer(1) and we need to be the contract deployer?
        // Actually, initialize can be called by anyone as long as it hasn't been initialized.
        // It checks msg.sender is a contract (Address.isContract). Our test contract is a contract.
        // So we can call initialize.

        // Create a ProductInfo struct. We need to set oracle to oracleAddress.
        // We need to provide all fields. Use fuzzed values for some, fixed for others.
        // To avoid reverts due to invalid payoff definition, we can use a simple one.
        // PayoffDefinition: payoffType and payoffDirection are enums. We can use 0 for both (Passthrough?)
        // But we don't know the enum values. We'll use a valid payoff definition that does not revert.
        // We'll assume the simplest: payoffType = 0 (PASSTHROUGH?), payoffDirection = 0 (LONG?), and data bytes30(0).
        // This should be valid.

        // Build ProductInfo
        IProduct.ProductInfo memory info;
        info.name = "Test";
        info.symbol = "TT";
        info.oracle = IOracleProvider(oracleAddress);
        info.payoffDefinition = PayoffDefinition(PayoffDefinitionLib.PayoffType.wrap(0), PayoffDefinitionLib.PayoffDirection.wrap(0), bytes30(0));
        info.maintenance = UFixed18.wrap(1e18);
        info.fundingFee = UFixed18.wrap(0);
        info.makerFee = UFixed18.wrap(0);
        info.takerFee = UFixed18.wrap(0);
        info.positionFee = UFixed18.wrap(0);
        info.makerLimit = UFixed18.wrap(type(uint256).max);
        // utilizationCurve: JumpRateUtilizationCurve with some values
        info.utilizationCurve = JumpRateUtilizationCurve(
            PackedFixed18.wrap(0),
            PackedFixed18.wrap(1e18),
            PackedFixed18.wrap(1e18),
            PackedUFixed18.wrap(1e18)
        );

        // We need to become the controller. The initializer stores msg.sender as controller.
        // Later, some functions use onlyProductOwner which checks controller.owner(). We don't need that.
        // We just need to initialize.
        c.initialize(info);

        // After initialization, the stored oracle address should be oracleAddress.
        // However, the mutant returns address(0) regardless.
        // So we assert that c.oracle() returns the stored address (which should be oracleAddress if everything went well).
        // But we cannot directly read the private storage. We can only observe via the public getter.
        // The reference returns the stored address; the mutant returns address(0).
        // Since we initialized with oracleAddress != address(0), and the initialization succeeded,
        // the reference will return oracleAddress (or maybe the address we set, which is oracleAddress).
        // The mutant returns address(0). So the property is: after initialization with a non-zero contract address,
        // oracle() must return that same address.
        assertEq(address(c.oracle()), oracleAddress);
    }
}

