pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address fuzzOracle, bytes calldata fuzzInitData) public {
        // Restrict to plausible contract addresses to keep domain wide
        vm.assume(fuzzOracle != address(0));
        vm.assume(fuzzOracle.code.length > 0);
        // Prepare init payload that will be used to initialize the contract with the fuzzed oracle
        // The fuzzer will explore different valid and invalid init payloads
        vm.prank(address(this));
        try c.initialize(
            IProduct.ProductInfo({
                name: "test",
                symbol: "T",
                payoffDefinition: PayoffDefinitionLib.create(
                    PayoffDefinitionLib.PayoffType.PASSTHROUGH,
                    PayoffDefinitionLib.PayoffDirection.LONG,
                    bytes30(0)
                ),
                oracle: IOracleProvider(fuzzOracle),
                maintenance: UFixed18.wrap(0),
                fundingFee: UFixed18.wrap(0),
                makerFee: UFixed18.wrap(0),
                takerFee: UFixed18.wrap(0),
                positionFee: UFixed18.wrap(0),
                makerLimit: UFixed18.wrap(0),
                utilizationCurve: JumpRateUtilizationCurve({
                    minRate: Fixed18.wrap(0),
                    maxRate: Fixed18.wrap(0),
                    targetRate: Fixed18.wrap(0),
                    targetUtilization: UFixed18.wrap(0)
                })
            })
        ) {} catch {}
        // After initialization attempt, oracle() must return the stored address if init succeeded,
        // or address(0) if init failed. The buggy mutant always returns address(0) regardless.
        // The property: oracle() must not return address(0) when the contract has a non-zero oracle stored.
        IOracleProvider returnedOracle = c.oracle();
        // If initialization succeeded, the stored oracle must be the fuzzed non-zero address.
        // If init failed, stored oracle is still address(0), but that's fine.
        // The crucial invariant: oracle() equals the actual stored oracle, which can be read via a public getter.
        // However, the bug always returns address(0), so we check: if the stored oracle is non-zero, oracle() must be non-zero.
        // We can infer stored oracle via the auto-generated public getter for the oracle state variable.
        // But UPayoffProvider stores oracle in a private constant slot, no public getter besides oracle().
        // Therefore, we can only check that oracle() is consistent with the initialized value.
        // We know the contract was initialized with fuzzOracle if the call didn't revert.
        // Instead, we check a simpler universal property: oracle() always returns an address that is either zero or a contract,
        // and we can detect the bug by checking that if we successfully set a non-zero oracle (by deploying a mock and initializing),
        // then oracle() must return that non-zero address.
        // Since the fuzzer provides fuzzOracle which is a contract, if initialization succeeds, oracle() must equal fuzzOracle.
        // The bug always returns address(0), so it will fail when fuzzOracle != address(0).
        // To know if initialization succeeded, we check if name() returns "test".
        bool initSucceeded = keccak256(abi.encodePacked(c.name())) == keccak256(abi.encodePacked("test"));
        if (initSucceeded) {
            assertTrue(returnedOracle == IOracleProvider(fuzzOracle));
        } else {
            // If init failed, oracle() might be zero, which is fine.
            assertTrue(true);
        }
    }
}

