contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed) public {
        // Use seed to generate valid initialization parameters
        // We need to initialize the contract first to test payoffDefinition
        // PayoffDefinition parameters are constructed from the seed

        // Bound seed to create valid PayoffType (0,1,2) and PayoffDirection (0,1)
        uint8 payoffTypeRaw = uint8(uint256(keccak256(abi.encode(seed, 0))) % 3);
        uint8 payoffDirRaw = uint8(uint256(keccak256(abi.encode(seed, 1))) % 2);
        bytes30 data = bytes30(uint240(uint256(keccak256(abi.encode(seed, 2)))));

        // Prepare ProductInfo for initialization
        IProduct.ProductInfo memory info;
        info.name = "test";
        info.symbol = "TST";
        info.payoffDefinition = PayoffDefinition(
            PayoffDefinitionLib.PayoffType(payoffTypeRaw),
            PayoffDefinitionLib.PayoffDirection(payoffDirRaw),
            data
        );
        info.oracle = IOracleProvider(address(0x1000000000000000000000000000000000000000));
        info.maintenance = UFixed18.wrap(1e17);
        info.fundingFee = UFixed18.wrap(1e16);
        info.makerFee = UFixed18.wrap(1e16);
        info.takerFee = UFixed18.wrap(1e16);
        info.positionFee = UFixed18.wrap(1e16);
        info.makerLimit = UFixed18.wrap(1e18);
        info.utilizationCurve = JumpRateUtilizationCurve(
            PackedFixed18.wrap(0),
            PackedFixed18.wrap(1e18),
            PackedFixed18.wrap(5e17),
            PackedUFixed18.wrap(8e17)
        );

        // Deploy an oracle contract that is a real contract (not an EOA)
        // We'll deploy a minimal contract at the oracle address
        vm.etch(address(info.oracle), hex"60006000fd"); // simple contract bytecode

        // Now we can initialize c as the controller
        vm.prank(address(c));
        c.initialize(info);

        // The property: payoffDefinition() must return what was stored during initialization
        PayoffDefinition memory expected = info.payoffDefinition;
        PayoffDefinition memory actual = c.payoffDefinition();

        // Assert that the actual payoffDefinition matches the expected one
        assertTrue(
            expected.equals(actual),
            "payoffDefinition should return stored definition"
        );
    }
}

