pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(int256 price) public {
        // 1. admissible domain: any int256 is valid oracle price
        // 2. deploy a minimal oracle mock and payoff that transforms price
        MockOracle oracle = new MockOracle();
        oracle.setPrice(price);
        PayoffDefinition memory payoff = PayoffDefinition({
            payoffType: PayoffDefinitionLib.PayoffType.PASSTHROUGH,
            payoffDirection: PayoffDefinitionLib.PayoffDirection.NEUTRAL,
            data: bytes30(0)
        });
        IProduct.ProductInfo memory info = IProduct.ProductInfo({
            name: "test",
            symbol: "TST",
            payoffDefinition: payoff,
            oracle: IOracleProvider(address(oracle)),
            maintenance: UFixed18.wrap(1e18),
            fundingFee: UFixed18.wrap(0),
            makerFee: UFixed18.wrap(0),
            takerFee: UFixed18.wrap(0),
            positionFee: UFixed18.wrap(0),
            makerLimit: UFixed18.wrap(1e18),
            utilizationCurve: JumpRateUtilizationCurve({
                minRate: PackedFixed18.wrap(0),
                maxRate: PackedFixed18.wrap(0),
                targetRate: PackedFixed18.wrap(0),
                targetUtilization: PackedUFixed18.wrap(0)
                })
        });
        c.initialize(info);

        // 3. the general property: currentVersion.price must equal payoff.transform(raw price)
        IOracleProvider.OracleVersion memory rawVersion = oracle.currentVersion();
        Fixed18 expectedPrice = payoff.transform(rawVersion.price);
        IOracleProvider.OracleVersion memory actualVersion = c.currentVersion();
        assertTrue(Fixed18.unwrap(actualVersion.price) == Fixed18.unwrap(expectedPrice));
    }
}

contract MockOracle is IOracleProvider {
    Fixed18 public price;
    function setPrice(int256 p) external { price = Fixed18.wrap(p); }
    function sync() external returns (OracleVersion memory) { return OracleVersion({version: 1, timestamp: block.timestamp, price: price}); }
    function currentVersion() external view returns (OracleVersion memory) { return OracleVersion({version: 1, timestamp: block.timestamp, price: price}); }
    function atVersion(uint256) external view returns (OracleVersion memory) { return currentVersion(); }
}

interface IOracleProvider {
    struct OracleVersion {
        uint256 version;
        uint256 timestamp;
        Fixed18 price;
    }
    function sync() external returns (OracleVersion memory);
    function currentVersion() external view returns (OracleVersion memory);
    function atVersion(uint256 oracleVersion) external view returns (OracleVersion memory);
}

