    PayoffDefinitionLib.PayoffDirection payoffDirection;
    bytes30 data;
}

library PayoffDefinitionLib {
    enum PayoffType { PASSTHROUGH }
    enum PayoffDirection { NEUTRAL }
    function transform(PayoffDefinition memory self, Fixed18 price) internal pure returns (Fixed18) { return price; }
    function valid(PayoffDefinition memory) internal pure returns (bool) { return true; }
}

