pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }
    function testFuzz_property(int256 rawPrice) public {
        // The oracle must return a price that is not the identity for the transformation.
        // We restrict rawPrice so that transform(rawPrice) != rawPrice for the default payoff definition.
        vm.assume(rawPrice > int256(1e18));
        vm.assume(rawPrice < type(int256).max / 1e18);

        // Deploy a mock oracle that returns the fuzzed raw price.
        MockOracle mockOracle = new MockOracle(rawPrice);

        // Create product info with a payoff definition that transforms price (e.g., scale by 2).
        // PayoffType 0 = PASSTHROUGH is not suitable because transform is identity.
        // Using PayoffType 1 (LINEAR) with a factor of 2 ensures transform(x) = 2*x.
        // PayoffDirection 0 = LONG is straightforward.
        bytes memory data = abi.encode(int256(2e18));
        PayoffDefinition memory payoffDef = PayoffDefinition({
            payoffType: PayoffDefinitionLib.PayoffType.wrap(1),
