// Minimal mock oracle that returns the supplied price.
contract MockOracle is IOracleProvider {
    int256 private immutable _rawPrice;
    constructor(int256 rawPrice) {
        _rawPrice = rawPrice;
    }
    function sync() external returns (OracleVersion memory) {}
    function currentVersion() external view returns (OracleVersion memory) {
        return OracleVersion({ version: 0, timestamp: 0, price: Fixed18.wrap(_rawPrice) });
