pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint64 _makerFee, uint64 _takerFee, uint64 _fundingFee) public {
        // All UFixed18 values must be <= 1e18 to be valid according to UFixed18Lib.from usage.
        // Bound to keep the domain wide but avoid revert on initialization.
        uint256 makerFee = bound(uint256(_makerFee), 0, 1e18);
        uint256 takerFee = bound(uint256(_takerFee), 0, 1e18);
        uint256 fundingFee = bound(uint256(_fundingFee), 0, 1e18);

        // Prepare a minimal product info to initialize the contract
        C.ProductInfo memory info;
        info.name = "test";
        info.symbol = "TEST";
        info.maintenance = UFixed18.wrap(1e18);
        info.fundingFee = UFixed18.wrap(fundingFee);
        info.makerFee = UFixed18.wrap(makerFee);
        info.takerFee = UFixed18.wrap(takerFee);
        info.positionFee = UFixed18.wrap(0);
        info.makerLimit = UFixed18.wrap(type(uint256).max);
        info.utilizationCurve = JumpRateUtilizationCurve({
            minRate: PackedFixed18.wrap(0),
            maxRate: PackedFixed18.wrap(int128(0)),
            targetRate: PackedFixed18.wrap(int128(0)),
            targetUtilization: PackedUFixed18.wrap(0)
        });
        // Oracle and payoff are set to zero addresses; initialize will fail unless we bypass the oracle check.
        // For the purpose of testing fundingFee, we can observe that the initialization will revert due to invalid oracle.
        // Since we cannot mock calls, we rely on the fact that the getter fundingFee() is accessible even if initialize reverted?
        // Actually, fundingFee() is a public getter of a storage variable. Even if initialize reverted, the storage remains zero.
        // The property we want to test is that fundingFee() returns the value that was set during initialization.
        // To test this, we need a successfully initialized contract. We cannot provide a real oracle address without deploying one.
        // This means that without a real oracle, initialization will revert.
        // However, the test harness constraints mandate that we interact only through c and only with the given contract.
        // We must work within the constraint: the getter fundingFee() is accessible, and we can compare it to the input we tried to set.
        // In the reference implementation, even if initialization fails, fundingFee() will return what was stored during the failed initialization
        // (because store happens before revert). In the buggy version, it always returns 0.
        // So we can simply call fundingFee() and assert it equals the value we attempted to set.
        try c.initialize(info) {} catch {}

        uint256 actual = UFixed18.unwrap(c.fundingFee());
        // The reference should return the stored value (which is fundingFee, because store happens before revert).
        // The buggy version always returns 0.
        assertEq(actual, fundingFee);
    }
}

