pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 newFF) public {
        newFF = bound(newFF, 1, 1e18);
        vm.assume(newFF > 0);
        c.updateFundingFee(abi.encodePacked(bytes32(newFF)));
        c.settle();
        uint256 ret = c.fundingFee();
        assertTrue(ret == newFF);
    }
}

