pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 rawFundingFee) public {
        rawFundingFee = bound(rawFundingFee, 1, 1e18);
        UFixed18 newFundingFee = UFixed18.wrap(rawFundingFee);
        vm.prank(address(this));
        c.updateFundingFee(newFundingFee);
        vm.prank(address(this));
        c.settle();
        UFixed18 returnedFee = c.fundingFee();
        assertTrue(returnedFee.unwrap() == newFundingFee.unwrap());
    }
}
